import std.collection.HashMap
import std.time.DateTime

class AccessGatewayFilter {
    public init() {
    }

    public func filter(request: HashMap<String, Any>): Bool {
        let path = request["path"] as String
        let method = request["method"] as String

        if (!is_start_with(path)) {
            return false
        }

        let user = get_jwt_user(request)
        match (user) {
            Some(u) => {
                set_current_user_info_and_log(u)
                return true
            }
            None => return false
        }
    }

    public func is_start_with(request_uri: String): Bool {
        if (request_uri.startsWith("/api") || request_uri.startsWith("/login")) {
            return true
        }
        return false
    }

    public func get_jwt_user(request: HashMap<String, Any>): Option<HashMap<String, Any>> {
        let headers = request["headers"] as HashMap<String, Any>
        let auth = headers["Authorization"] as HashMap<String, Any>
        let jwt = auth["jwt"] as String
        let user = auth["user"] as HashMap<String, Any>
        let currentDate = DateTime.now().format("yyyy-MM-dd")

        if (jwt == user["name"] as String + currentDate) {
            return Some(user)
        } else {
            return None
        }
    }

    public func set_current_user_info_and_log(user: HashMap<String, Any>): Unit {
        let name = user["name"] as String
        let address = user["address"] as String
        let log = HashMap<String, String>([
            ("name", name),
            ("address", address),
            ("time", DateTime.now().toString())
        ])
        println("Access log: ${log}")
    }
}

