import std.collection.*
import std.reflect.*
import std.convert.*

class ArgumentParser {
    let arguments: HashMap<String, Any>
    let required: HashSet<String>
    let types: HashMap<String, TypeInfo>

    public init() {
        arguments = HashMap<String, Any>()
        required = HashSet<String>()
        types = HashMap<String, TypeInfo>()
    }

    public func parse_arguments(command_string: String): (Bool, Option<HashSet<String>>) {
        let tokens = command_string.split("\\s+")
        let args = HashSet<String>()
        let opts = HashSet<String>()
        let values = HashMap<String, String>()
        let missing = HashSet<String>()

        var i = 0
        while i < tokens.size() {
            let token = tokens[i]
            if token.startsWith("--") {
                if token.contains("=") {
                    let parts = token.split("=")
                    let arg = parts[0].substring(2)
                    values[arg] = parts[1]
                    args.add(arg)
                } else {
                    let arg = token.substring(2)
                    args.add(arg)
                }
            } else if token.startsWith("-") {
                let opt = token.substring(1)
                opts.add(opt)
            }
            i += 1
        }

        for arg in required {
            if !args.contains(arg) {
                missing.add(arg)
            }
        }

        if !missing.isEmpty() {
            return (false, Some(missing))
        }

        for arg in args {
            let value = values[arg].unwrapOrElse(() => "")
            arguments[arg] = convert_type(arg, value)
        }

        for opt in opts {
            arguments[opt] = true
        }

        (true, None)
    }

    public func get_argument(key: String): Any {
        arguments[key]
    }

    public func add_argument(arg: String, required!: Bool = false, arg_type!: TypeInfo = TypeInfo.of<String>()): Unit {
        types[arg] = arg_type
        if required {
            required.add(arg)
        }
    }

    public func convert_type(arg: String, value: String): Any {
        let type_info = types.get(arg)
        if type_info.isNone() {
            return value
        }

        let type = type_info.unwrap()
        if type == TypeInfo.of<Int64>() {
            return value.toInt64()
        } else if type == TypeInfo.of<Float64>() {
            return value.toFloat64()
        } else if type == TypeInfo.of<Bool>() {
            return value.toBool()
        } else {
            return value
        }
    }
}

