import std.collection.HashMap
import std.collection.ArrayList
import std.unicode.UnicodeStringExtension

class AutomaticGuitarSimulator {

    /*
    Thisclassisanautomaticguitarsimulatorthatcaninterpretandplaybasedontheinputguitarsheetmusic.
    */

    let play_text: String

    public init(text: String) {
        /*
        Initializethescoretobeplayed
        :param text:String,scoretobeplayed
        */
        this.play_text = text
    }

    public func interpret(display!: Bool = false): ArrayList<HashMap<String, String>> {
        /*
        Interpretthemusicscoretobeplayed
        :param display:Bool,representingwhethertoprinttheinterpretedscore
        :return:listofHashMap,TheHashMaptwofields,ChordandTune,whicharelettersandnumbers,respectively.Iftheinputisemptyorcontainsonlywhitespace,anemptylistisreturned.
        >>>context=AutomaticGuitarSimulator("C53231323Em43231323F43231323G63231323")
        >>>play_list=context.interpret(display:false)
        [{'Chord':'C','Tune':'53231323'},{'Chord':'Em','Tune':'43231323'},{'Chord':'F','Tune':'43231323'},{'Chord':'G','Tune':'63231323'}]

        */
        let result = ArrayList<HashMap<String, String>>()
        if (this.play_text.trim().length() == 0) {
            return result
        }
        let parts = this.play_text.split(" ")
        for (part in parts) {
            let chordEndIndex = part.findFirstMatch(Regex("[0-9]")).getOrElse(-1)
            if (chordEndIndex == -1) {
                continue
            }
            let chord = part.substring(0, chordEndIndex)
            let tune = part.substring(chordEndIndex)
            let item = HashMap<String, String>()
            item.add("Chord", chord)
            item.add("Tune", tune)
            result.add(item)
            if (display) {
                println(this.display(chord, tune))
            }
        }
        return result
    }

    public func display(key: String, value: String): String {
        /*
        Printoutchordandplaytunewithfollowingformat:NormalGuitarPlaying--Chord:%s,PlayTune:%s
        :param key:String,chord
        :param value:String,playtune
        :return:String
        >>>context=AutomaticGuitarSimulator("C53231323Em43231323F43231323G63231323")
        >>>context.display("C","53231323")
        NormalGuitarPlaying--Chord:C,PlayTune:53231323

        */
        return "Normal Guitar Playing -- Chord: " + key + ", Play Tune: " + value
    }
}

