import std.collection.ArrayList

class BalancedBrackets {

    let stack: ArrayList<String>
    let left_brackets: ArrayList<String>
    let right_brackets: ArrayList<String>
    var expr: String

    public init(expr: String) {
        this.stack = ArrayList<String>()
        this.left_brackets = ArrayList<String>(["(", "{", "["])
        this.right_brackets = ArrayList<String>([")", "}", "]"])
        this.expr = expr
    }

    public func clear_expr(): Unit {
        let filtered = ArrayList<String>()
        for (c in this.expr.characters()) {
            if (this.left_brackets.contains(c) || this.right_brackets.contains(c)) {
                filtered.add(c)
            }
        }
        this.expr = filtered.join("")
    }

    public func check_balanced_brackets(): Bool {
        this.clear_expr()
        this.stack.clear()
        let bracket_map = HashMap<String, String>([(")", "("), ("}", "{"), ("]", "[")])

        for (c in this.expr.characters()) {
            if (this.left_brackets.contains(c)) {
                this.stack.add(c)
            } else if (this.right_brackets.contains(c)) {
                if (this.stack.size == 0 || this.stack[this.stack.size - 1] != bracket_map[c]) {
                    return false
                }
                this.stack.remove(this.stack.size - 1)
            }
        }
        return this.stack.size == 0
    }
}

