import std.convert.Parsable

class BigNumCalculator {

    public static func add(num1: String, num2: String): String {
        let result = ArrayList<Int64>()
        let carry = 0
        let i = num1.size - 1
        let j = num2.size - 1

        while (i >= 0 || j >= 0 || carry > 0) {
            let digit1 = if (i >= 0) { num1[i].toString().parseInt64().get() } else { 0 }
            let digit2 = if (j >= 0) { num2[j].toString().parseInt64().get() } else { 0 }
            let sum = digit1 + digit2 + carry
            result.add(sum % 10)
            carry = sum / 10
            i--
            j--
        }

        return result.reverse().map({x => x.toString()}).join("")
    }

    public static func subtract(num1: String, num2: String): String {
        let isNegative = false
        if (num1.size < num2.size || (num1.size == num2.size && num1 < num2)) {
            let temp = num1
            num1 = num2
            num2 = temp
            isNegative = true
        }

        let result = ArrayList<Int64>()
        let borrow = 0
        let i = num1.size - 1
        let j = num2.size - 1

        while (i >= 0) {
            let digit1 = num1[i].toString().parseInt64().get() - borrow
            let digit2 = if (j >= 0) { num2[j].toString().parseInt64().get() } else { 0 }

            if (digit1 < digit2) {
                digit1 += 10
                borrow = 1
            } else {
                borrow = 0
            }

            result.add(digit1 - digit2)
            i--
            j--
        }

        while (result.size > 1 && result[result.size - 1] == 0) {
            result.remove(result.size - 1)
        }

        let resStr = result.reverse().map({x => x.toString()}).join("")
        return if (isNegative) { "-${resStr}" } else { resStr }
    }

    public static func multiply(num1: String, num2: String): String {
        if (num1 == "0" || num2 == "0") {
            return "0"
        }

        let m = num1.size
        let n = num2.size
        let pos = ArrayList<Int64>(m + n).fill(0)

        for (i in (0..m).reverse()) {
            for (j in (0..n).reverse()) {
                let mul = num1[i].toString().parseInt64().get() * num2[j].toString().parseInt64().get()
                let p1 = i + j
                let p2 = i + j + 1
                let sum = mul + pos[p2]

                pos[p1] += sum / 10
                pos[p2] = sum % 10
            }
        }

        let sb = ArrayList<String>()
        for (num in pos) {
            if (!(sb.size == 0 && num == 0)) {
                sb.add(num.toString())
            }
        }

        return if (sb.size == 0) { "0" } else { sb.join("") }
    }
}

