import std.convert.RadixConvertible

class BinaryDataProcessor {

    var binary_string: String

    public init(binary_string: String) {
        this.binary_string = binary_string
        this.clean_non_binary_chars()
    }

    public func clean_non_binary_chars(): Unit {
        var cleaned = ""
        for char in this.binary_string {
            if char == '0' || char == '1' {
                cleaned += char
            }
        }
        this.binary_string = cleaned
    }

    public func calculate_binary_info(): HashMap<String, Float64> {
        var zeros = 0
        var ones = 0
        for char in this.binary_string {
            if char == '0' {
                zeros += 1
            } else if char == '1' {
                ones += 1
            }
        }
        var total = zeros + ones
        var result = HashMap<String, Float64>()
        result.insert("Zeroes", Float64(zeros) / Float64(total))
        result.insert("Ones", Float64(ones) / Float64(total))
        result.insert("Bit length", Float64(total))
        return result
    }

    public func convert_to_ascii(): String {
        var result = ""
        var i = 0
        while i < this.binary_string.length() - 7 {
            var byteStr = this.binary_string.substring(i, i + 8)
            var byte = Int64.parse(byteStr, 2)
            result += Rune(byte.toUInt8()).toString()
            i += 8
        }
        return result
    }

    public func convert_to_utf8(): String {
        var result = ""
        var i = 0
        while i < this.binary_string.length() {
            var byteSize = 1
            if this.binary_string.substring(i, i + 1) == "0" {
                byteSize = 1
            } else if this.binary_string.substring(i, i + 3) == "110" {
                byteSize = 2
            } else if this.binary_string.substring(i, i + 4) == "1110" {
                byteSize = 3
            } else if this.binary_string.substring(i, i + 5) == "11110" {
                byteSize = 4
            }

            if i + byteSize * 8 > this.binary_string.length() {
                break
            }

            var bytes = Array<UInt8>(byteSize)
            for j in 0..<byteSize {
                var byteStr = this.binary_string.substring(i + j * 8, i + (j + 1) * 8)
                bytes[j] = UInt8(Int64.parse(byteStr, 2))
            }

            var tuple = Rune.fromUtf8(bytes, 0)
            result += tuple[0].toString()
            i += byteSize * 8
        }
        return result
    }
}

