```cangjie
import std.collection.ArrayList

class BoyerMooreSearch {

    let text: String
    let pattern: String
    let textLen: Int64
    let patLen: Int64

    public init(text: String, pattern: String) {
        this.text = text
        this.pattern = pattern
        this.textLen = text.size
        this.patLen = pattern.size
    }

    public func match_in_pattern(char: String): Int64 {
        for (i in (patLen - 1)..=0 step -1) {
            if (pattern[i] == char) {
                return i
            }
        }
        return -1
    }

    public func mismatch_in_text(currentPos: Int64): Int64 {
        for (i in 0..patLen) {
            if (pattern[i] != text[currentPos + i]) {
                return currentPos + i
            }
        }
        return -1
    }

    public func bad_character_heuristic(): ArrayList<Int64> {
        let positions = ArrayList<Int64>()
        if (patLen == 0 || textLen == 0 || patLen > textLen) {
            return positions
        }
        var skip: Int64
        for (i in 0..=(textLen - patLen)) {
            skip = 0
            for (j in (patLen - 1)..=0 step -1) {
                if (pattern[j] != text[i + j]) {
                    skip = j - match_in_pattern(text[i + j])
                    if (skip < 1) {
                        skip = 1
                    }
                    break
                }
            }
            if (skip == 0) {
                positions.add(i)
                skip = patLen
            }
        }
        return positions
    }
}
