import std.collection.HashMap
import std.collection.ArrayList
import std.convert.Parsable

class Calculator {

    let operators: HashMap<String, (Float64, Float64) -> Float64>

    public init() {
        this.operators = HashMap<String, (Float64, Float64) -> Float64>()
        operators.add("+", {x: Float64, y: Float64 => x + y})
        operators.add("-", {x: Float64, y: Float64 => x - y})
        operators.add("*", {x: Float64, y: Float64 => x * y})
        operators.add("/", {x: Float64, y: Float64 => x / y})
        operators.add("^", {x: Float64, y: Float64 => x ** y})
    }

    public func calculate(expression: String): Option<Float64> {
        let operand_stack = ArrayList<Float64>()
        let operator_stack = ArrayList<String>()
        var i = 0
        while (i < expression.size) {
            let c = expression[i]
            if (c == ' ') {
                i++
                continue
            }
            if (c == '(') {
                operator_stack.add("(")
                i++
            } else if (c == ')') {
                while (operator_stack.size > 0 && operator_stack.last != "(") {
                    let (new_operand_stack, new_operator_stack) = this.apply_operator(operand_stack, operator_stack)
                    operand_stack = new_operand_stack
                    operator_stack = new_operator_stack
                }
                operator_stack.pop()
                i++
            } else if (this.operators.contains(c.toString())) {
                while (operator_stack.size > 0 && this.precedence(operator_stack.last) >= this.precedence(c.toString())) {
                    let (new_operand_stack, new_operator_stack) = this.apply_operator(operand_stack, operator_stack)
                    operand_stack = new_operand_stack
                    operator_stack = new_operator_stack
                }
                operator_stack.add(c.toString())
                i++
            } else {
                var num = ""
                while (i < expression.size && (expression[i].isDigit() || expression[i] == '.')) {
                    num += expression[i]
                    i++
                }
                let parsed = Float64.tryParse(num)
                if (parsed.isNone()) {
                    return Option<Float64>.None
                }
                operand_stack.add(parsed.unwrap())
            }
        }
        while (operator_stack.size > 0) {
            let (new_operand_stack, new_operator_stack) = this.apply_operator(operand_stack, operator_stack)
            operand_stack = new_operand_stack
            operator_stack = new_operator_stack
        }
        if (operand_stack.size == 1) {
            return Option<Float64>.Some(operand_stack[0])
        } else {
            return Option<Float64>.None
        }
    }

    public func precedence(op: String): Int64 {
        if (op == "+" || op == "-") {
            1
        } else if (op == "*" || op == "/") {
            2
        } else if (op == "^") {
            3
        } else {
            0
        }
    }

    public func apply_operator(operand_stack: ArrayList<Float64>, operator_stack: ArrayList<String>): (ArrayList<Float64>, ArrayList<String>) {
        let op = operator_stack.pop()
        let y = operand_stack.pop()
        let x = operand_stack.pop()
        let fn = this.operators.get(op).unwrap()
        operand_stack.add(fn(x, y))
        (operand_stack, operator_stack)
    }
}

