import std.time.DateTime
import std.collection.ArrayList

class Event <: Equatable<Event> {
    let date: DateTime
    let start_time: DateTime
    let end_time: DateTime
    let description: String

    public init(date: DateTime, start_time: DateTime, end_time: DateTime, description: String) {
        this.date = date
        this.start_time = start_time
        this.end_time = end_time
        this.description = description
    }

    public override operator func != (that: Event): Bool {
        return this.date != that.date || this.start_time != that.start_time || this.end_time != that.end_time || this.description != that.description
    }

    public override operator func == (that: Event): Bool {
        return this.date == that.date && this.start_time == that.start_time && this.end_time == that.end_time && this.description == that.description
    }
}

class CalendarUtil {
    let events: ArrayList<Event>

    public init() {
        this.events = ArrayList<Event>()
    }

    public func add_event(event: Event): Unit {
        this.events.append(event)
    }

    public func remove_event(event: Event): Unit {
        let index = this.events.indexOf(event)
        if (index >= 0) {
            this.events.remove(index)
        }
    }

    public func get_events(date: DateTime): ArrayList<Event> {
        let result = ArrayList<Event>()
        for (event in this.events) {
            if (event.date.year == date.year && event.date.month == date.month && event.date.dayOfMonth == date.dayOfMonth) {
                result.append(event)
            }
        }
        return result
    }

    public func is_available(start_time: DateTime, end_time: DateTime): Bool {
        for (event in this.events) {
            if (!(end_time.compare(event.start_time) == Ordering.LT || start_time.compare(event.end_time) == Ordering.GT)) {
                return false
            }
        }
        return true
    }

    public func get_available_slots(date: DateTime): ArrayList<(DateTime, DateTime)> {
        let result = ArrayList<(DateTime, DateTime)>()
        let day_start = DateTime.of(year: date.year, month: date.month, dayOfMonth: date.dayOfMonth, hour: 0, minute: 0)
        let day_end = DateTime.of(year: date.year, month: date.month, dayOfMonth: date.dayOfMonth + 1, hour: 0, minute: 0)
        let day_events = this.get_events(date)

        day_events.sort(stable: true, comparator!: (e1: Event, e2: Event) -> Ordering {
            return e.start_time.compare(e2.start_time)
        })

        var current_start = day_start
        for (event in day_events) {
            if (current_start.compare(event.start_time) == Ordering.LT) {
                result.append((current_start, event.start_time))
            }
            if (event.end_time.compare(current_start) == Ordering.GT) {
                current_start = event.end_time
            }
        }

        if (current_start.compare(day_end) == Ordering.LT) {
            result.append((current_start,day_end))
        }

        return result
    }

    public func get_upcoming_events(num_events: Int64): ArrayList<Event> {
        let now = DateTime.now()
        let upcoming = ArrayList<Event>()

        for (event in this.events) {
            if (event.start_time.compare(now) == Ordering.GT) {
                upcoming.append(event)
            }
        }

        upcoming.sort(stable: true, comparator!: (e1: Event, e2: Event) -> Ordering {
            return e1.start_time.compare(e2.start_time)
        })

        if (upcoming.size > num_events) {
            return upcoming[0..num_events]
        }
        return upcoming
    }
}

