import std.collection.ArrayList

class ChandrasekharSieve {

    let n: Int64
    var primes: ArrayList<Int64> = ArrayList<Int64>()

    public init(n: Int64) {
        this.n = n
        this.primes = generate_primes()
    }

    public func generate_primes(): ArrayList<Int64> {
        if n < 2 {
            return ArrayList<Int64>()
        }
        let sieve: ArrayList<Bool> = ArrayList<Bool>(n.toInt32(), true)
        sieve[0] = false
        sieve[1] = false
        var i: Int64 = 2
        while i * i <= n {
            if sieve[i.toInt32()] {
                var j: Int64 = i * i
                while j <= n {
                    sieve[j.toInt32()] = false
                    j += i
                }
            }
            i += 1
        }
        primes.clear()
        var k: Int64 = 0
        while k <= n {
            if sieve[k.toInt32()] {
                primes.add(k)
            }
            k += 1
        }
        return primes
    }

    public func get_primes(): ArrayList<Int64> {
        return primes
    }
}

