import std.collection.ArrayList
import std.fs.*
import std.io.*
import std.unicode.UnicodeStringExtension

class CSVProcessor {

    public init() {}

    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        let path = Path(file_name)
        let file = File(path, Read)
        let contents = readToEnd(file)
        file.close()

        let lines = String.fromUtf8(contents).split("\n")
        let title = ArrayList<String>()
        let data = ArrayList<ArrayList<String>>()

        for (i, line) in lines.enumerated() {
            if line.isEmpty() { continue }
            let cells = line.split(",")
            if i == 0 {
                title.addAll(cells)
            } else {
                let row = ArrayList<String>()
                row.addAll(cells)
                data.add(row)
            }
        }

        return (title, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        let path = Path(file_name)
        let file = File(path, Write)

        for row in data {
            let line = row.join(",") + "\n"
            file.write(line.toArray())
        }

        file.close()
        return 1
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        let (title, original_data) = read_csv(save_file_name)
        let new_data = ArrayList<ArrayList<String>>()

        for row in original_data {
            let new_row = ArrayList<String>()
            if N < row.size() {
                new_row.add(row.get(N).toUpperCase())
            }
            new_data.add(new_row)
        }

        let new_title = ArrayList<String>()
        if N < title.size() {
            new_title.add(title.get(N))
        }

        let processed_data = ArrayList<ArrayList<String>>()
        processed_data.add(new_title)
        processed_data.addAll(new_data)

        let new_file_name = save_file_name.substring(0, save_file_name.lastIndexOf(".")) + "_process.csv"
        return write_csv(processed_data, new_file_name)
    }
}

