import std.collection.HashMap
import std.collection.ArrayList
import std.math.round
import std.math.abs
import std.sort.sort

class DataStatistics {

    public func mean(data: ArrayList<Int64>): Float64 {
        if data.size == 0 {
            return 0.0
        }
        let sum = data.reduce(0, |acc, x| acc + x)
        let mean = sum.toFloat64() / data.size.toFloat64()
        return round(mean * 100) / 100
    }

    public func median(data: ArrayList<Int64>): Float64 {
        if data.size == 0 {
            return 0.0
        }
        let sortedData = sort(data)
        if sortedData.size % 2 == 1 {
            return sortedData[sortedData.size / 2].toFloat64()
        } else {
            let mid = sortedData.size / 2
            return round((sortedData[mid - 1] + sortedData[mid]).toFloat64() / 2 * 100) / 100
        }
    }

    public func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        if data.size == 0 {
            return ArrayList<Int64>()
        }
        let freqMap = HashMap<Int64, Int64>()
        for num in data {
            freqMap.put(num, freqMap.getOrDefault(num, 0) + 1)
        }
        let maxFreq = freqMap.values().max() ?? 0
        let modes = ArrayList<Int64>()
        for (num, freq) in freqMap {
            if freq == maxFreq {
                modes.add(num)
            }
        }
        return sort(modes)
    }
}

