import std.collection.ArrayList
import std.math.round
import std.math.sqrt
import std.math.abs

class DataStatistics2 {

    /*
    This is a class for performing data statistics, supporting to get the sum, minimum, maximum, variance, standard deviation, and correlation of a given dataset.
    */

    let data: ArrayList<Float64>

    public init(data: ArrayList<Float64>) {
        /*
        Initialize Data List
        :param data:ArrayList<Float64>
        */
        this.data = data
    }

    public func get_sum(): Float64 {
        /*
        Calculate the sum of data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_sum()
        10.0
        */
        var sum: Float64 = 0.0
        for (num in this.data) {
            sum += num
        }
        return sum
    }

    public func get_min(): Float64 {
        /*
        Calculate the minimum value in the data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_min()
        1.0
        */
        var min_val = this.data[0]
        for (num in this.data) {
            if (num < min_val) {
                min_val = num
            }
        }
        return min_val
    }

    public func get_max(): Float64 {
        /*
        Calculate the maximum value in the data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4]))
        >>> ds2.get_max()
        4.0
        */
        var max_val = this.data[0]
        for (num in this.data) {
            if (num > max_val) {
                max_val = num
            }
        }
        return max_val
    }

    public func get_variance(): Float64 {
        /*
        Calculate variance, accurate to two digits after the Decimal separator
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_variance()
        1.25
        */
        let mean = this.get_sum() / this.data.size()
        var variance: Float64 = 0.0
        for (num in this.data) {
            variance += (num - mean) * (num - mean)
        }
        variance /= this.data.size()
        return round(variance * 100) / 100
    }

    public func get_std_deviation(): Float64 {
        /*
        Calculate standard deviation, accurate to two digits after the Decimal separator
        :return:Float64
        >>> ds二年 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_std_deviation()
        1.12
        */
        return round(sqrt(this.get_variance()) * 100) / 100
    }

    public func get_correlation(): Float64 {
        /*
        Calculate correlation
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_correlation()
        1.0
        */
        let n = this.data.size()
        let sum_x = this.get_sum()
        let sum_y = sum_x
        var sum_xy: Float64 = 0.0
        var sum_x2: Float64 = 0.0
        var sum_y2: Float64 = 0.0

        for (i in 0..n) {
            sum_xy += this.data[i] * this.data[i]
            sum_x2 += this.data[i] * this.data[i]
            sum_y2 += this.data[i] * this.data[i]
        }

        let numerator = sum_xy - (sum_x * sum_y) / n
        let denominator = sqrt((sum_x2 - sum_x * sum_x / n) * (sum_y2 - sum_y * sum_y / n))
        return numerator / denominator
    }
}

