import std.collection.ArrayList
import std.math.sqrt
import std.math.exp
import std.math.abs

class DataStatistics4 {

    public static func correlation_coefficient(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        let n = data1.size()
        let sum1 = data1.stream().reduce(0.0, (a, b) -> a + b)
        let sum2 = data2.stream().reduce(0.0, (a, b) -> a + b)
        let sum1_sq = data1.stream().reduce(0.0, (a squared)
        let sum2_sq = data2.stream().reduce(0.0, (a, b) -> a + b * b)
        let p_sum = (0..<n).stream().reduce(0.0, (a, i) -> a + data1.get(i) * data2.get(i))
        let num = p_sum - (sum1 * sum2 / n.toFloat64())
        let den = sqrt((sum1_sq - sum1 * sum1 / n.toFloat64()) * (sum2_sq - sum2 * sum2 / n.toFloat64()))
        return num / den
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        let n = data.size()
        let mean = data.stream().reduce(0.0, (a, b) -> a + b) / n.toFloat64()
        let variance = data.stream().reduce(0.0, (a, b) -> a + (b - mean) * (b - mean)) / (n - 1).toFloat64()
        let std_dev = sqrt(variance)
        let skewness = data.stream().reduce(0.0, (a, b) -> a + ((b - mean) / std_dev) * ((b - mean) / std_dev) * ((b - mean) / std_dev)) / n.toFloat64()
        return skewness
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        let n = data.size()
        let mean = data.stream().reduce(0.0, (a, b) -> a + b) / n.toFloat64()
        let variance = data.stream().reduce(0.0, (a, b) -> a + (b - mean) * (b - mean)) / (n - 1).toFloat64()
