import std.collection.ArrayList

class EightPuzzle {

    let initial_state: ArrayList<ArrayList<Int64>>
    let goal_state: ArrayList<ArrayList<Int64>>

    public init(initial_state: ArrayList<ArrayList<Int64>>) {
        this.initial_state = initial_state
        this.goal_state = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([1, 2, 3]), ArrayList<Int64>([4, 5, 6]), ArrayList<Int64>([7, 8, 0])])
    }

    public func find_blank(state: ArrayList<ArrayList<Int64>>): (Int64, Int64) {
        for (i in 0..state.size) {
            for (j in 0..state[i].size) {
                if (state[i][j] == 0) {
                    return (i, j)
                }
            }
        }
        return (-1, -1)
    }

    public func move(state: ArrayList<ArrayList<Int64>>, direction: String): ArrayList<ArrayList<Int64>> {
        let new_state = state.copy()
        let (i, j) = find_blank(new_state)

        match (direction) {
            case "up" => {
                if (i > 0) {
                    let temp = new_state[i][j]
                    new_state[i][j] = new_state[i-1][j]
                    new_state[i-1][j] = temp
                }
            }
            case "down" => {
                if (i < new_state.size - 1) {
                    let temp = new_state[i][j]
                    new_state[i][j] = new_state[i+1][j]
                    new_state[i+1][j] = temp
                }
            }
            case "left" => {
                if (j > 0) {
                    let temp = new_state[i][j]
                    new_state[i][j] = new_state[i][j-1]
                    new_state[i][j-1] = temp
                }
            }
            case "right" => {
                if (j < new_state[i].size - 1) {
                    let temp = new_state[i][j]
                    new_state[i][j] = new_state[i][j+1]
                    new_state[i][j+1] = temp
                }
            }
        }

        return new_state
    }

    public func get_possible_moves(state: ArrayList<ArrayList<Int64>>): ArrayList<String> {
        let moves = ArrayList<String>()
        let (i, j) = find_blank(state)

        if (i > 0) {
            moves.add("up")
        }
        if (i < state.size - 1) {
            moves.add("down")
        }
        if (j > 0) {
            moves.add("left")
        }
        if (j < state[i].size - 1) {
            moves.add("right")
        }

        return moves
    }

    public func solve(): ArrayList<String> {
        let open_list = ArrayList<ArrayList<ArrayList<Int64>>>()
        let paths = ArrayList<ArrayList<String>>()

        open_list.add(this.initial_state)
        paths.add(ArrayList<String>())

        while (!open_list.isEmpty()) {
            let current_state = open_list.remove(0)
            let current_path = paths.remove(0)

            if (current_state == this.goal_state) {
                return current_path
            }

            let moves = get_possible_moves(current_state)
            for (move in moves) {
                let new_state = move(current_state, move)
                let new_path = current_path.copy()
                new_path.add(move)
                open_list.add(new_state)
                paths.add(new_path)
            }
        }

        return ArrayList<String>()
    }
}

