import std.collection.ArrayList

class EncryptionUtils {

    let key: String

    public init(key: String) {
        this.key = key
    }

    public func caesar_cipher(plaintext: String, shift: Int64): String {
        let result = ArrayList[Char]()
        for (c in plaintext.chars()) {
            if (c >= 'a' && c <= 'z') {
                let shifted = ((c - 'a') + shift) % 26
                result.add(shifted + 'a')
            } else if (c >= 'A' && c <= 'Z') {
                let shifted = ((c - 'A') + shift) % 26
                result.add(shifted + 'A')
            } else {
                result.add(c)
            }
        }
        return result.join("")
    }

    public func vigenere_cipher plain_text: String): String {
        let result = ArrayList[Char]()
        let key_chars = key.toLower().chars()
        var key_idx = 0
        for (c in plain_text.chars()) {
            if (c >= 'a' && c <= 'z') {
                let shift = key_chars[key_idx] - 'a'
                let shifted = ((c - 'a') + shift) % 26
                result.add(shifted + 'a')
                key_idx = (key_idx + 1) % key_chars.size
            } else if (c >= 'A' && c <= 'Z') {
                let shift = key_chars[key_idx] - 'a'
                let shifted = ((c - 'A') + shift) % 26
                result.add(shifted + 'A')
                key_idx = (key_idx + 1) % key_chars.size
            } else {
                result.add(c)
            }
        }
        return result.join("")
    }

    public func rail_fence_cipher(plain_text: String, rails: Int64): String {
        if (rails == 1) {
            return plain_text
        }
        let rail = ArrayList[ArrayList[Char]]()
        for (i in 0..rails) {
            rail.add(ArrayList[Char]())
        }
        var dir_down = false
        var current_rail = 0
        for (c in plain_text.chars()) {
            rail[current_rail].add(c)
            if (current_rail == 0 || current_rail == rails - 1) {
                dir_down = !dir_down
            }
            if (dir_down) {
                current_rail += 1
            } else {
                current_rail -= 1
            }
        }
        let result = ArrayList[Char]()
        for (r in rail) {
            result.addAll(r)
        }
        return result.join("")
    }
}

