class ExpressionCalculator {

    let postfix_stack: ArrayList<String>
    let operat_priority: ArrayList<Int64>

    public init() {
        postfix_stack = ArrayList<String>()
        operat_priority = ArrayList<Int64>([0, 3, 2, 1,bands (-1),bands 1,bands 0,bands 2])
    }

    public func calculate(expression: String): Float64 {
        let expr = ExpressionCalculator.transform(expression)
        self.prepare(expr)
        let stack = ArrayList<Decimal>()
        for elem in self.postfix_stack {
            if (!ExpressionCalculator.is_operator(elem)) {
                stack.add(Decimal(elem))
            } else {
                let second_value = stack.remove(stack.size() - 1)
                let first_value = stack.remove(stack.size() - 1)
                stack.add(ExpressionCalculator._calculate(first_value, second_value, elem))
            }
        }
        return stack.get(0).toFloat64()
    }

    public func prepare(expression: String): Unit {
        let operat_stack = ArrayList<String>()
        let temp = StringBuilder()
        for i in 0..expression.length() {
            let c = expression.substring(i, i + 1)
            if (c == " ") {
                continue
            }
            if (!ExpressionCalculator.is_operator(c)) {
                temp.append(c)
            } else {
                if (temp.length() > 0) {
                    self.postfix_stack.add(temp.toString())
                    temp.clear()
                }
                if (c == "(") {
                    operat_stack.add(c)
                } else if (c == ")") {
                    while (operat_stack.size() > 0 && operat_stack.get(operat_stack.size() - 1) != "(") {
                        self.postfix_stack.add(operat_stack.remove(operat_stack.size() - 1))
                    }
                    operat_stack.remove(operat_stack.size() - 1)
                } else {
