            self.postfix_stack.add(temp.toString())
        }
        while (operat_stack.size() > 0) {
            self.postfix_stack.add(operat_stack.remove(operat_stack.size() - 1))
        }
    }

    public static func is_operator(c: String): Bool {
        return "+-*/()%".indexOf(c) != -1
    }

    public func compare(cur: String, peek: String): Bool {
        let cur_pri = self.operat_priority.get("+-*/%".indexOf(cur))
        let peek_pri = self.operat_priority.get("+-*/%".indexOf(peek))
        return cur_pri <= peek_pri
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        return match current_op {
            "+" => first_value + second_value,
            "-" => first_value - second_value,
            "*" => first_value * second_value,
            "/" => first_value / second_value,
            "%" => first_value % second_value,
            _ => Decimal(0)
        }
    }

    public static func transform(expression: String): String {
        return Regex.replace("\\s+").with("").from(expression)
    }
