import std.collection.HashMap

class Hotel {
    let name: String
    let available_rooms: HashMap<String, Int64>
    var booked_rooms: HashMap<String, HashMap<String, Int64>>

    public init(name: String, rooms: HashMap<String, Int64>) {
        this.name = name
        this.available_rooms = HashMap<String, Int64>(rooms)
        this.booked_rooms = HashMap<String, HashMap<String, Int64>>()
    }

    public func book_room(room_type: String, room_number: Int64,name: String): String {
        if (!this.available_rooms.containsKey(room_type)) {
            return "false"
        }
        let remaining = this.available_rooms[room_type]
        if (remaining == 0) {
            return "false"
        }
        if (room_number <= remaining) {
            this.available_rooms[room_type] = remaining - room_number
            if (!this.booked_rooms.containsKey(room_type)) {
                this.booked_rooms[room_type] = HashMap<String, Int64>()
            }
            let guest_rooms = this.booked_rooms[room_type]
            guest_rooms[name] = guest_rooms.getOrElse(name, 0) + room_number
            return "Success!"
        } else {
            return remaining.toString()
        }
    }

    public func check_in(room_type: String, room_number: Int64, name: String): Bool {
        if (!this.booked_rooms.containsKey(room_type)) {
            return false
        }
        let guest_bookings = this.booked_rooms[room_type]
        if (!guest_bookings.containsKey(name)) {
            return false
        }
        let booked = guest_bookings[name]
        if (room_number > booked) {
            return false
        }
        if (room_number == booked) {
            guest_bookings.remove(name)
        } else {
            guest_bookings[name] = booked - room_number
        }
        return true
    }

    public func check_out(room_type: String, room_number: Int64): Unit {
        let current = this.available_rooms.getOrElse(room_type, 0)
        this.available_rooms[room_type] = current + room_number
    }

    public func get_available_rooms(room_type: String): Int64 {
        return this.available_rooms.getOrElse(room_type, 0)
    }
}

