import std.collection.ArrayList

class Interpolation {

    public static func interpolate_1d(x: ArrayList<Float64>, y: ArrayList<Float64>, x_interp: ArrayList<Float64>): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        for xi in x_interp {
            let idx = x.lowerBound(xi)
            if idx == 0 {
                result.append(y[0])
            } elif idx == x.size {
                result.append(y[y.size - 1])
            } else {
                let x0 = x[idx - 1]
                let x1 = x[idx]
                let y0 = y[idx - 1]
                let y1 = y[idx]
