import std.convert.Parsable
import std.convert.Formattable
import std.collection.ArrayList

class IPAddress {

    let ip_address: String

    public init(ip_address: String) {
        this.ip_address = ip_address
    }

    public func is_valid(): Bool {
        let parts = ip_address.split(".")
        if parts.len != 4 {
            return false
        }
        for part in parts {
            if !part.isDigit() {
                return false
            }
            let num = part.toInt()
            if num < 0 || num > 255 {
                return false
            }
        }
        return true
    }

    public func get_octets(): ArrayList<String> {
        let octets = ArrayList<String>()
        if !is_valid() {
            return octets
        }
        octets.addAll(ip_address.split("."))
        return octets
    }

    public func get_binary(): String {
        if !is_valid() {
            return ""
        }
        let octets = get_octets()
        let binaryParts = ArrayList<String>()
        for octet in octets {
            let num = octet.toInt()
            binaryParts.add(num.toBinary().padLeft(8, '0'))
        }
        return binaryParts.join(".")
    }
}

