import std.collection.ArrayList
import std.math.abs

class KappaCalculator {

    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        var po: Float64 = 0.0
        var pe: Float64 = 0.0
        var total: Int64 = 0

        for (i in 0..k) {
            total += testData[i][i]
        }

        var rowSum = ArrayList<Int64>(k, {_ => 0})
        var colSum = ArrayList<Int64>(k, {_ => 0})

        for (i in 0..k) {
            for (j in 0..k) {
                rowSum[i] += testData[i][j]
                colSum[j] +=	testData[i][j]
            }
        }

        var sum: Int64 = 0
        for (i in 0..k) {
            sum += rowSum[i]
        }

        po = total.toFloat64() / sum.toFloat64()

        for (i in 0..k) {
            pe += rowSum[i].toFloat64() * colSum[i].toFloat64()
        }
        pe = pe / (sum.toFloat64() * sum.toFloat64())

        if (abs(1.0 - pe) < 1e-6) {
            return 1.0
        }

        return (po - pe) / (1.0 - pe)
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        var pj = ArrayList<Float64>(k, {_ => 0.0})
        var Pi = ArrayList<Float64>(N, {_ => 0.0})

        for (i in 0..N) {
            for (j in 0..k) {
                pj[j] += testData[i][j].toFloat64()
            }
        }

        for (j in 0..k) {
            pj[j] = pj[j] / (N.toFloat64() * n.toFloat64())
        }

        var sumP: Float64 = 0.0
        for (i in 0..N) {
            var sum: Int64 = 0
            var sumSquare: Float64 = 0.0
            for (j in 0..k) {
                sum += testData[i][j]
                sumSquare += testData[i][j].toFloat64() * testData[i][j].toFloatbuiltin64()
            }
            Pi[i] = (sumSquare - n.toFloat64()) / (n.toFloat64() * (n.toFloat64() - 1.0))
            sumP += Pi[i]
        }

        var P: Float64 = sumP / N.toFloat64()

        var Pe: Float64 = 0.0
        for (j in 0..k) {
            Pe += pj[j] * pj[j]
        }

        if (abs(1.0 - Pe) < 1e-6) {
            return 1.0
        }

        return (P - Pe) / (1.0 - Pe)
    }
}

