import std.collection.ArrayList
import std.regex.Regex

class LongestWord {

    let word_list: ArrayList<String>

    public init() {
        this.word_list = ArrayList<String>()
    }

    public func add_word(word: String): Unit {
        this.word_list.add(word)
    }

    public func find_longest_word(sentence: String): String {
        if (this.word_list.isEmpty()) {
            return ""
        }
        let r = Regex("[^a-zA-Z\\s]")
        let cleanedSentence = r.replaceAll(sentence, "")
        let words = cleanedSentence.split(" ")
        let mut longestWord = ""
        for (word in words) {
            if (this.word_list.contains(word) && word.size() > longestWord.size()) {
                longestWord = word
            }
        }
        return longestWord
    }
}

