class Manacher {

    let input_string: String

    public init(input_string: String) {
        this.input_string = input_string
    }

    public func palindromic_length(center: Int64, diff: Int64, string: String): Int64 {
        if (center - diff == -1 || center + diff == string.size || string[(center - diff).toInt32()] != string[(center + diff).toInt32()]) {
            return 0
        }
        return 1 + palindromic_length(center, diff + 1, string)
    }

    public func palindromic_string(): String {
        let max_len = 0
        let max_substring = ""
        let new_string = "#" + "#".join(input_string.toArray()) + "#"

        for (i in 0..new_string.size) {
            let length = palindromic_length(i, 1, new_string)
            if (length > max_len) {
                max_len = length
                max_substring = new_string[(i - length).toInt32()..(i + length + 1).toInt32()].filter(c => c != '#').join()
            }
        }
        return max_substring
    }
}
