class MetricsCalculator2 {

    public init() {}

    public static func mrr(data: Any): (Float64, ArrayList<Float64>) {
        let isList = data is ArrayList<Any>
        let dataList = if isList { data as ArrayList<Any> } else { ArrayList<Any>([data]) }
        let mrrList = ArrayList<Float64>()
        let mrrSum = Float64(0.0)

        for item in dataList {
            let (actual, _) = item as (ArrayList<Int64>, Int64)
            let mrr = Float64(0.0)
            for (i, val) in actual.enumerated() {
                if val == 1 {
                    mrr = Float64(1.0) / Float64(i + 1)
                    break
                }
            }
            mrrList.add(mrr)
            mrrSum += mrr
        }

        let avgMrr = mrrSum / Float64(dataList.size())
        return (avgMrr, mrrList)
    }

    public static func map(data: Any): (Float64, ArrayList<Float64>) {
        let isList = data is ArrayList<Any>
        let dataList = if isList { data as ArrayList<Any> } else { ArrayList<Any>([data]) }
        let mapList = ArrayList<Float64>()
        let mapSum = Float64(0.0)

        for item in dataList {
            let (actual, gtNum) = item as (ArrayList<Int64>, Int64)
            let ap = Float64(0.0)
            let correctCount = Int64(0)
            let precisionSum = Float64(0.0)

            for (i, val) in actual.enumerated() {
                if val == 1 {
                    correctCount += 1
                    precisionSum += Float64(correctCount) / Float64(i + 1)
                }
            }

            ap = if gtNum > 0 { precisionSum / Float64(gtNum) } else { Float64(0.0) }
            mapList.add(ap)
            mapSum += ap
        }

        let avgMap = mapSum / Float64(dataList.size())
        return (avgMap, mapList)
    }
}

