import std.convert.Parsable
import std.unicode.UnicodeStringExtension

class NumberWordFormatter {

    let NUMBER: Array<String>
    let NUMBER_TEEN: Array<String>
    let NUMBER_TEN: Array<String>
    let NUMBER_MORE: Array<String>
    let NUMBER_SUFFIX: Array<String>

    public init() {
        this.NUMBER = ["", "ONE", "TWO", "THREE", FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        this.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN",
                            "NINETEEN"]
        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        match x {
            Some(value) => return this.format_string(value),
            None => return "ZERO ONLY"
        }
    }

    public func format_string(x: String): String {
        var parts = x.split(".")
        var integerPart = parts[0]
        var decimalPart = if parts.len() > 1 then parts[1] else ""

        var word = this.parse_integer(integerPart)
        if decimalPart != "" {
            word += " POINT " + this.parse_decimal(decimalPart)
        }
        return word + " ONLY"
    }

    func parse_integer(s: String): String {
        if s == "0" {
            return "ZERO"
        }

        var s = s.trimLeft('0')
        if s == "" {
            return "ZERO"
        }

        var length = s.len()
        var groups = (length + 2) / 3
        var words = ""

        for i in 0..groups {
            var start = max(0, length - (i + 1) * 3)
            var end = length - i * 3
            var slice = s.slice(start, end)
            var groupWord = this.trans_three(slice)
            if groupWord != "" {
                if i > 0 {
                    groupWord += " " + this.NUMBER_MORE[i]
                }
                if words != "" {
                    words = groupWord + " " + words
                } else {
                    words = groupWord
                }
            }
        }
        return words
    }

    func parse_decimal(s: String): String {
        var words = ""
        for c in s.chars() {
            var digit = c.toString().parseInt()
            words += this.NUMBER[digit] + " "
        }
        return words.trim()
    }

    public func trans_two(s: String): String {
        var num = s.parseInt()
        if num < 10 {
            return this.NUMBER[num]
        } else if num < 20 {
            return this.NUMBER_TEEN[num - 10]
        } else {
            var tens = num / 10
            var units = num % 10
            var word = this.NUMBER_TEN[tens - 1]
            if units != 0 {
                word += " " + this.NUMBER[units]
            }
            return word
        }
    }

    public func trans_three(s: String): String {
        var num = s.parseInt()
        if num == 0 {
            return ""
        }

        var s = s.padLeft(3, '0')
        var hundreds = s[0].toString().parseInt()
        var rest = s.slice(1, 3).parseInt()

        var word = ""
        if hundreds != 0 {
            word += this.NUMBER[hundreds] + " HUNDRED"
        }

        if rest != 0 {
            if hundreds != 0 {
                word += " AND "
            }
            word += this.trans_two(rest.toString())
        }
        return word
    }

    public func parse_more(i: Int64): String {
        if i >= 0 && i < this.NUMBER_MORE.len() {
            return this.NUMBER_MORE[i]
        }
        return ""
    }
}

