import std.collection.ArrayList
import std.convert.RadixConvertible

class NumericEntityUnescaper {

    public init() {}

    public func replace(string: String): String {
        var result = StringBuilder()
        var i = 0
        while i < string.length() {
            var current = string.charAt(i)
            if current == r'&' && i + 1 < string.length() && string.charAt(i + 1) == r'#' {
                var j = i + 2
                var is_hex = false
                if j < string.length() && (string.charAt(j) == r'x' || string.charAt(j) == r'X') {
                    is_hex = true
                    j++
                }
                var num_start = j
                while j < string.length() && string.charAt(j).isDigit() || (is_hex && NumericEntityUnescaper.is_hex_char(string.charAt(j))) {
                    j++
                }
                if j < string.length() && string.charAt(j) == r';' {
                    var num_str = string.substring(num_start, j)
                    var num: Int64 = 0
                    if is_hex {
                        num = num_str.toInt64(Radix.HEX)
                    } else {
                        num = num_str.toInt64()
                    }
                    if num >= 0 && num <= 0x10FFFF {
                        result.append(Rune(num))
                        i = j + 1
                        continue
                    }
                }
            }
            result.append(current)
            i++
        }
        return result.toString()
    }

    public static func is_hex_char(char: Rune): Bool {
        return (char >= r'0' && char <= r'9') || (char >= r'a' && char <= r'f') || (char >= r'A' && char <= r'F')
    }
}

