import std.collection.ArrayList

class PushBoxGame {

    let map: ArrayList<ArrayList<String>>
    var player_row: Int64
    var player_col: Int64
    let targets: ArrayList<ArrayList<Int64>>
    let boxes: ArrayList<ArrayList<Int64>>
    var target_count: Int64
    var is_game_over: Bool

    public init(map: ArrayList<ArrayList<String>>) {
        this.map = map
        this.player_row = 0
        this.player_col = 0
        this.targets = ArrayList<ArrayList<Int64>>()
        this.boxes = ArrayList<ArrayList<Int64>>()
        this.target_count = 0
        this.is_game_over = false

        func init_game() {
            for (i in 0..map.size) {
                for (j in 0..map[i].size) {
                    if (map[i][j] == "O") {
                        player_row = i
                        player_col = j
                    } else if (map[i][j] == "G") {
                        targets.add(ArrayList<Int64>([i, j]))
                        target_count += 1
                    } else if (map[i][j] == "X") {
                        boxes.add(ArrayList<Int64>([i, j]))
                    }
                }
            }
        }
        init_game()
    }

    public func check_win(): Bool {
        var count = 0
        for (box in boxes) {
            for (target in targets) {
                if (box[0] == target[0] && box[1] == target[1]) {
                    count += 1
                    break
                }
            }
        }
        is_game_over = (count == target_count)
        return is_game_over
    }

    public func move(direction: String): Bool {
        var new_row = player_row
        var new_col = player_col

        match (direction) {
            case "w" => new_row -= 1
            case "s" => new_row += 1
            case "a" => new_col -= 1
            case "d" => new_col += 1
            case _ => return false
        }

        if (new_row < 0 || new_row >= map.size || new_col < 0 || new_col >= map[0].size) {
            return false
        }

        if (map[new_row][new_col] == "#") {
            return false
        }

        var box_index = -1
        for (i in 0..boxes.size) {
            if (boxes[i][0] == new_row && boxes[i][1] == new_col) {
                box_index = i
                break
            }
        }

        if (box_index != -1) {
            var box_new_row = new_row + (new_row - player_row)
            var box_new_col = new_col + (new_col - player_col)

            if (box_new_row < 0 || box_new_row >= map.size || box_new_col < 0 || box_new_col >= map[0].size) {
                return false
            }

            if (map[box_new_row][box_new_col] == "#") {
                return false
            }

            for (box in boxes) {
                if (box[0] == box_new_row && box[1] == box_new_col) {
                    return false
                }
            }

            boxes[box_index][0] = box_new_row
            boxes[box_index][1] = box_new_col
        }

        map[player_row][player_col] = " "
        player_row = new_row
        player_col = new_col
        map[player_row][player_col] = "O"

        return check_win()
    }
}

