class RPGCharacter {
    let name: String
    var hp: Int64
    var attack_power: Int64
    var defense: Int64
    var level: Int64
    var exp: Int64

    public init(name: String, hp: Int64, attack_power: Int64, defense: Int64, level!: Int64 = 1) {
        this.name = name
        this.hp = hp
        this.attack_powerattack_power = attack_power
        this.defense = defense
        this.level = level
        this.exp = 0
    }

    public func attack(other_character: RPGCharacter): Unit {
        let damage = max(0, this.attack_power - other_character.defense)
        other_character.hp = max(0, other_character.hp - damage)
        if (!other_character.is_alive()) {
            this.gain_exp(other_character.level * 100)
        }
    }

    public func heal(): Int64 {
        this.hp = min(100, this.hp + 10)
        return this.hp
    }

    public func gain_exp(amount: Int64): Unit {
        var remaining_exp = amount
        while (remaining_exp > 0 && this.level < 100) {
            let needed_exp = this.level * 100 - this.exp
            let exp_gained = min(remaining_exp, needed_exp)
            this.exp += exp_gained
            remaining_exp -= exp_gained
            if (this.exp >= this.level * 100) {
                let (new_level, new_hp, new_attack, new_defense) = this.level_up()
                this.level = new_level
                this.hp = new_hp
                this.attack_power = new_attack
                this.defense = new_defense
            }
        }
    }

    public func level_up(): (Int64, Int64, Int64, Int64) {
        if (this.level >= 100) {
            return (this.level, this.hp, this.attack_power, this.defense)
        }
        this.exp = 0
        this.level += 1
        this.hp += 20
        this.attack_power += 5
        this.defense += 5
        return (this.level, this.hp, this.attack_power, this.defense)
    }

    public func is_alive(): Bool {
        return this.hp > 0
    }
}

