import std.collection.ArrayList
import std.random.Random

class Snake {

    var length: Int64
    let SCREEN_WIDTH: Int64
    let SCREEN_HEIGHT: Int64
    let BLOCK_SIZE: Int64
    var positions: ArrayList<ArrayList<Int64>>
    var score: Int64
    var food_position: ArrayList<Int64>

    public init(SCREEN_WIDTH: Int64, SCREEN_HEIGHT: Int64, BLOCK_SIZEdomain: Int64, food_position: ArrayList<Int64>) {
        this.length = 1
        this.SCREEN_WIDTH = SCREEN_WIDTH
        this.SCREEN_HEIGHT = SCREEN_HEIGHT
        this.BLOCK_SIZE = BLOCK_SIZE
        this.positions = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([SCREEN_WIDTH / 2, SCREEN_HEIGHT / 2])])
        this.score = 0
        this.food_position = food_position
    }

    public func move(direction: ArrayList<Int64>): Unit {
        let head = this.positions[0].clone()
        head[0] += direction[0] * this.BLOCK_SIZE
        head[1] += direction[1] * this.BLOCK_SIZE
        this.positions.insert(0, head)
        if (head.equals(this.food_position)) {
            this.eat_food()
        } else {
            this.positions.removeAt(this.positions.size - 1)
        }
        for (i in 1..this.positions.size) {
            if (head.equals(this.positions[i])) {
                this.reset()
                break
            }
        }
    }

    public func random_food_position(): Unit {
        let rand = Random()
        loop {
            let new_pos = ArrayList<Int64>([rand.nextInt(SCREEN_WIDTH / BLOCK_SIZE) * BLOCK_SIZE, rand.nextInt(SCREEN_HEIGHT / BLOCK_SIZE) * BLOCK_SIZE])
            var conflict = false
            for (pos in this.positions) {
                if (pos.equals(new_pos)) {
                    conflict = true
                    break
                }
            }
            if (!conflict) {
                this.food_position = new_pos
                break
            }
        }
    }

    public func reset(): Unit {
        this.length = 1
        this.positions = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([SCREEN_WIDTH / 2, SCREEN_HEIGHT / 2])])
        this.score = 0
        this.random_food_position()
    }

    public func eat_food(): Unit {
        this.length += 1
        this.score += 100
        this.random_food_position()
    }
}

