import std.collection.ArrayList
import std.collection.HashMap
import std.math.abs
import std.sort.sort
import std.math.sqrt

class Statistics3 {

    public static func median(data: ArrayList<Int64>): Float64 {
        if (data.isEmpty) {
            return 0.0
        }
        let sortedData = data.clone()
        sort(sortedData)
        let n = sortedData.size
        if (n % 2 == 0) {
            return (sortedData[n/2 - 1] + sortedData[n/2]) / 2.0
        } else {
            return sortedData[n/2] * 1.0
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let frequencyMap = HashMap<Int64, Int64>()
        for (num in data) {
            frequencyMap.put(num, frequencyMap.getOrDefault(num, 0) + 1)
        }
        let maxFrequency = frequencyMap.values.max()
        let modes = ArrayList<Int64>()
        for (entry in frequencyMap.entries) {
            if (entry.value == maxFrequency) {
                modes.add(entry.key)
            }
        }
        sort(modes)
        return modes
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        if (x.size != y.size || x.isEmpty) {
            return Option.None
        }
        let n = x.size
        let sumX = x.sum()
        let sumY = y.sum()
        let sumXY = x.zip(y).map({(a, b) => a * b}).sum()
        let sumX2 = x.map({a => a * a}).sum()
        let sumY2 = y.map({a => a * a}).sum()
        let numerator = n * sumXY - sumX * sumY
        let denominator = sqrt((n * sumX2 - sumX * sumX) * (n * sumY2 - sumY * sumY))
        if (denominator == 0.0) {
            return Option.None
        }
        return Option.Some(numerator / denominator)
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        if (data.isEmpty) {
            return Option.None
        }
        return Option.Some(data.sum() * 1.0 / data.size)
    }

    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
        let n = data.size
        let matrix = ArrayList<ArrayList<Float64>>()
        for (i in 0..n) {
            let row = ArrayList<Float64>()
            for (j in 0..n) {
                let corr = correlation(data[i], data[j])
                row.add(corr.getOrDefault(0.0))
            }
            matrix.add(row)
        }
        return matrix
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        if (data.isEmpty) {
            return Option.None
        }
        let m = mean(data).get()
        let variance = data.map({x => (x - m) * (x - m)}).sum() / data.size
        return Option.Some(sqrt(variance))
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        if (data.isEmpty) {
            return Option.None
        }
        let m = mean(data).get()
        let std = standard_deviation(data).get()
        if (std == 0.0) {
            return Option.None
        }
        let zScores = data.map({x => (x - m) / std})
        return Option.Some(zScores)
    }
}

