import std.collection.ArrayList
import std.collection.HashMap
import std.math.abs

class Stock <: Equatable<Stock> {

    let name: String
    var price: Float64
    var quantity: Int64

    public init(name: String, price: Float64,quantity: Int64) {
        this.name = name
        this.price = price
        this.quantity = quantity
    }

    public override operator func != (that: Stock): Bool {
        return this.name != that.name || this.price != that.price || this.quantity != that.quantity
    }

    public override operator func == (that: Stock): Bool {
        return this.name == that.name && this.price == that.price && this.quantity == that.quantity
    }
}

class StockPortfolioTracker {

    var portfolio: ArrayList<Stock>
    var cash_balance: Float64

    public init(cash_balance: Float64) {
        this.portfolio = ArrayList<Stock>()
        this.cash_balance = cash_balance
    }

    public func add_stock(stock: Stock): Unit {
        this.portfolio.add(stock)
    }

    public func remove_stock(stock: Stock): Bool {
        return this.portfolio.remove(stock)
    }

    public func buy_stock(stock: Stock): Bool {
        let total_cost = stock.price * stock.quantity.toFloat64()
        if (total_cost > this.cash_balance) {
            return false
        }
        this.cash_balance -= total_cost
        this.portfolio.add(stock)
        return true
    }

    public func sell_stock(stock: Stock): Bool {
        let existing = this.portfolio.find(s => s.name == stock.name)
        if (existing == None || existing.get().quantity < stock.quantity) {
            return false
        }
        let existing_stock = existing.get()
        existing_stock.quantity -= stock.quantity
        this.cash_balance += stock.price * stock.quantity.toFloat64()
        if (existing_stock.quantity == 0) {
            this.portfolio.remove(existing_stock)
        }
        return true
    }

    public func calculate_portfolio_value(): Float64 {
        var total = this.cash_balance
        for (stock in this.portfolio) {
            total += stock.price * stock.quantity.toFloat64()
        }
        return total
    }

    public func get_portfolio_summary(): (Float64, ArrayList<HashMap<String, Any>>) {
        var summary = ArrayList<HashMap<String, Any>>()
        var total_value = this.cash_balance
        for (stock in this.portfolio) {
            let stock_value = stock.price * stock.quantity.toFloatdegree64()
            total_value += stock_value
            var stock_summary = HashMap<String, Any>()
            stock_summary.put("name", stock.name)
            stock_summary.put("value", stock_value)
            summary.add(stock_summary)
        }
        return (total_value, summary)
    }

    public func get_stock_value(stock: Stock): Float64 {
        return stock.price * stock.quantity.toFloat64()
    }
}

