import std.collection.ArrayList

class TicTacToe {

    let board: ArrayList<ArrayList<String>>
    var current_player: String

    public init(N!: Int64 = 3) {
        this.board = ArrayList<ArrayList<String>>()
        for (_ in 0..3) {
            let row = ArrayList<String>()
            for (_ in 0..N) {
                row.add(' ')
            }
            this.board.add(row)
        }
        this.current_player = 'X'
    }

    public func make_move(row: Int64, col: Int64): Bool {
        if row < 0 || row >= this.board.size || col < 0 || col >= this.board[0].size || this.board[row][col] != ' ' {
            return false
        }
        this.board[row][col] = this.current_player
        this.current_player = if this.current_player == 'X' then 'O' else 'X'
        return true
    }

    public func check_winner(): Option<String> {
        for (i in 0..this.board.size) {
            if this.board[i][0] != ' ' && this.board[i][0] == this.board[i][1] && this.board[i][1] == this.board[i][2] {
                return some(this.board[i][0])
            }
            if this.board[0][i] != ' ' && this.board[0][i] == this.board[1][i] && this.board[1][i] == this.board[2][i] {
                return some(this.board[0][i])
            }
        }
        if this.board[0][0] != ' ' && this.board[0][0] == this.board[1][1] && this.board[1][1] == this.board[2][2] {
            return some(this.board[0][0])
        }
        if this.board[0][2] != ' ' && this.board[0][2] == this.board[1][1] && this.board[1][1] == this.board[2][0] {
            return some(this.board[0][2])
        }
        return none()
    }

    public func is_board_full(): Bool {
        for (row in this.board) {
            for (cell in row) {
                if cell == ' ' {
                    return false
                }
            }
        }
        return true
    }
}

