import std.time.DateTime
import std.math.round

class TimeUtils {

    let datetime: DateTime

    public init() {
        this.datetime = DateTime.now()
    }

    public func get_current_time(): String {
        this.datetime.format("HH:mm:ss")
    }

    public func get_current_date(): String {
        this.datetime.format("yyyy-MM-dd")
    }

    public func add_seconds(seconds: Int64): String {
        this.datetime.addSeconds(seconds).format("HH:mm:ss")
    }

    public func string_to_datetime(string: String): DateTime {
        DateTime.parse(string, "yyyy-MM-dd HH:mm:ss")
    }

    public func datetime_to_string(datetime: DateTime): String {
        datetime.format("yyyy-MM-dd HH:mm:ss")
    }

    public func get_minutes(string_time1: String, string_time2: String): Int64 {
        let datetime1 = DateTime.parse(string_time1, "yyyy-MM-dd HH:mm:ss")
        let datetime2 = DateTime.parse(string_time2, "yyyy-MM-dd HH:mm:ss")
        let seconds = (datetime2.toEpochSecond() - datetime1.toEpochSecond())
        round(float(seconds) / 60.0).toInt64()
    }

    public func get_format_time(year: Int64, month: Int64, day: Int64, hour: Int64, minute: Int64, second: Int64): String {
        DateTime.of(
            year: year,
            month: month,
            dayOfMonth: day,
            hour: hour,
            minute: minute,
            second: second,
            timeZone: TimeZone.load("UTC")
        ).format("yyyy-MM-dd HH:mm:ss")
    }
}

