import std.math.numeric.Decimal
import std.math.numeric.round
import std.math.abs

class TriCalculator {

    let PI = 3.1415926

    public init() {}

    public func cos(x: Float64): Float64 {
        let radians = x * PI / 180.0
        let normalized = radians % (2 * PI)
        var result = 0.0
        var term = 1.0
        var sign = 1
        var i = 0
        while abs(term) > 1e-15 {
            result += term
            sign *= -1
            i += 2
            term = sign * pow(normalized, Float64(i)) / Float64(self.factorial(Int64(i)).toDouble())
        }
        return round(result, 14)
    }

    public func factorial(a: Int64): Decimal {
        if a <= 1 { return Decimal(1) }
        var result = Decimal(1)
        for i in 2..=a {
            result *= Decimal(i)
        }
        return result
    }

    public func taylor(x: Float64, n: Int64): Float64 {
        let radians = x * PI / 180.0
        var result = 0.0
        var sign = 1
        for i in 0..n {
            let exponent = 2 * i
            let term = sign * pow(radians, Float64(exponent)) / Float64(self.factorial(Int64(exponent)).toDouble())
            result += term
            sign *= -1
        }
        return result
    }

    public func sin(x: Float64): Float64 {
        let radians = x * PI / 180.0
        let normalized = radians % (2 * PI)
        var result = 0.0
        var term = normalized
        var sign = 1
        var i = 1
        while abs(term) > 1e-15 {
            result += term
            sign *= -1
            i += 2
            term = sign * pow(normalized, Float64(i)) / Float64(self.factorial(Int64(i)).toDouble())
        }
        return round(result, 14)
    }

    public func tan(x: Float64): Option<Float64> {
        let cos_val = self.cos(x)
        if abs(cos_val) < 0.000001 {
            return None
        }
        return Some(self.sin(x) / cos_val)
    }
}

