import std.collection.HashMap

class URLHandler {
    let url: String

    public init(url: String) {
        this.url = url
    }

    public func get_scheme(): Option<String> {
        let parts = this.url.split("://")
        if (parts.size != 2) {
            return Option.none()
        }
        return Option.some(parts[0])
    }

    public func get_host(): Option<String> {
        let schemeParts = this.url.split("://")
        if (schemeParts.size != 2) {
            return Option.none()
        }
        let hostPathParts = schemeParts[1].split("/", maxSplit: 1)
        return Option.some(hostPathParts[0])
    }

    public func get_path(): Option<String> {
        let schemeParts = this.url.split("://")
        if (schemeParts.size != 2) {
            return Option.none()
        }
        let hostPathParts = schemeParts[1].split("/", maxSplit: 1)
        if (hostPathParts.size == 1) {
            return Option.some("")
        }
        return Option.some("/" + hostPathParts[1])
    }

    public func get_query_params(): Option<HashMap<String, String>> {
        let pathOpt = this.get_path()
        if (pathOpt.isNone()) {
            return Option.none()
        }
        let path = pathOpt.getOrThrow()
        let queryFragmentParts = path.split("#", maxSplit: 1)
        let queryPart = queryFragmentParts[0]
        let queryParamParts = queryPart.split("?", maxSplit: 1)
        if (queryParamParts.size == 1) {
            return Option.some(HashMap<String, String>())
        }
        let queryParamsStr = queryParamParts[1]
        let paramPairs = queryParamsStr.split("&")
        let result = HashMap<String, String>()
        for (pair in paramPairs) {
            let keyValue = pair.split("=", maxSplit: 1)
            if (keyValue.size == 2) {
                result.add(keyValue[0], keyValue[1])
            }
        }
        return Option.some(result)
    }

    public func get_fragment(): Option<String> {
        let pathOpt = this.get_path()
        if (pathOpt.isNone()) {
            return Option.none()
        }
        let path = pathOpt.getOrThrow()
        let queryFragmentParts = path.split("#",	maxSplit: 1)
        if (queryFragmentParts.size == 1) {
            return Option.none()
        }
        return Option.some(queryFragmentParts[1])
    }
}

