import std.collection.HashMap
import std.collection.ArrayList
import std.math.abs
import std.math.sqrt
import std.math.log
import std.math.pow

class VectorUtil {

    public static func similarity(vector_1: ArrayList<Float64>, vector_2: ArrayList<Float64>): Float64 {
        let dot = vector_1.zip(vector_2).map({(a, b) => a * b}).sum()
        let norm_a = sqrt(vector_1.map({x => x * x}).sum())
        let norm_b = sqrt(vector_2.map({x => x * x}).sum())
        dot / (norm_a * norm_b)
    }

    public static func cosine_similarities(vector_1: ArrayList<Float64>, vectors_all: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        vectors_all.map({vec => similarity(vector_1, vec)})
    }

    public static func n_similarity(vector_list_1: ArrayList<ArrayList<Float64>>, vector_list_2: ArrayList<ArrayList<Float64>>): Float64 {
        let vec1 = vector_list_1.map({vec => vec}).reduce({a, b => a.zip(b).map({(x, y) => x + y})})
        let vec2 = vector_list_2.map({vec => vec}).reduce({a, b => a.zip(b).map({(x, y) => x + y})})
        similarity(vec1, vec2)
    }

    public static func compute_idf_weight_dict(total_num: Int64, number_dict: HashMapnombre<String, Float64>): HashMap<String, Float64> {
        let dict = HashMap<String, Float64>()
        for ((key, count) in number_dict) {
            dict[key] = log((total_num.toFloat64() + 1.0) / (count + 1.0))
        }
        dict
    }
}

