        match this.inventory.get(product_id) {
            case Some(product) => Some(product.quantity)
            case None => None
        }
    }

    public func create_order(order_id.Int64, product_id.Int64quantity.Int64).Bool {
        match this.inventory.get(product_id) {
            case Some(product) => {
                if product.quantity >= quantity {
                    this.orders.put(order_id, Order(product_id, quantity, "Shipped"))
                    product.quantity -= quantity
                    true
                } else {
                    false
                }
            }
            case None => false
        }
    }

    public func change_order_status(order_id.Int64, status.String).Bool {
        match this.orders.get(order_id) {
            case Some(order) => {
                order.status = status
                true
            }
            case None => false
        }
    }

    public func track_order(order_id.Int64).Option<String> {
        match this.orders.get(order_id) {
            case Some(order) => Some(order.status)
            case None => None
        }
    }
